/**
 * Renders the one tool identified by `slug`. Unknown slugs import nothing and
 * render a defensive placeholder (the server page already calls notFound()).
 */
export default function ToolMount({ slug }: { slug: string }): React.ReactElement {
  const Component = TOOL_COMPONENTS[slug];
  if (!Component) {
    return <div data-testid="tool-mount-missing" />;
  }
  return <Component {...({} as ToolProps)} />;
}
